// Um tipo exporta-se e importa-se com a mesma sintaxe que qualquer valor: e essa a
// novidade que o TypeScript acrescenta ao sistema de modulos que ja se conhece.
export interface Utilizador {
  nome: string;
  ativo: boolean;
}

export type Papel = 'admin' | 'editor' | 'leitor';

export function criarUtilizador(nome: string, papel: Papel): Utilizador {
  return { nome, ativo: papel !== 'leitor' };
}

const u = criarUtilizador('Rita', 'admin');
console.log(u); // { nome: 'Rita', ativo: true }

interface Config {
  nome: string;
}

function criarConfig(nome: string): Config {
  return { nome };
}

interface Metadata {
  versao: number;
}

function obterVersao(): Metadata {
  return { versao: 2 };
}

// export type marca este export como so-tipo: nao produz nada no JavaScript emitido.
export type { Config };

// Modificador "type" por especificador: mistura um tipo e um valor na mesma linha.
export { type Metadata, obterVersao };

export { criarConfig };

console.log(criarConfig('producao')); // { nome: 'producao' }
console.log(obterVersao()); // { versao: 2 }

// Config foi exportado como so-tipo porque nunca existiu como valor: uma interface
// nao gera nenhum construtor nem nenhuma funcao em runtime. O erro abaixo e so de
// compilacao, mas o try/catch protege a demonstracao caso o exemplo corra mesmo assim.
try {
  // @ts-expect-error Config e so um tipo: nao existe nenhum valor com este nome em runtime
  new Config();
} catch (erro) {
  console.log('nem chega a compilar; se corresse, falharia em runtime:', (erro as Error).message);
}

// Ate aqui, sem import nem export, este ficheiro e um script: as suas declaracoes de
// topo entram no ambito global do programa.
function saudar(nome: string): string {
  return `Ola, ${nome}`;
}
console.log(saudar('Ana')); // Ola, Ana

// A partir daqui o ficheiro passa a ter um export (mesmo vazio): torna-se um modulo,
// com o seu proprio ambito. As declaracoes de topo deixam de ir para o ambito global
// partilhado com outros ficheiros do mesmo programa.
export {};

interface Pedido {
  id: number;
  total: number;
}

function calcularTotalComIva(pedido: Pedido, taxa: number): number {
  return pedido.total * (1 + taxa);
}

export type { Pedido };
export { calcularTotalComIva };

const pedido: Pedido = { id: 1, total: 100 };
console.log(calcularTotalComIva(pedido, 0.2)); // 120

