interface Produto {
  nome: string;
  preco: number;
}

function formatarProduto(p: Produto): string {
  return `${p.nome} - ${p.preco}€`;
}

export type { Produto };
export { formatarProduto };

const caneca: Produto = { nome: 'Caneca', preco: 8.5 };
console.log(formatarProduto(caneca)); // Caneca - 8.5€

type Estado = 'ativo' | 'inativo';

function verificarEstado(e: Estado): boolean {
  return e === 'ativo';
}

export { type Estado, verificarEstado };

console.log(verificarEstado('ativo')); // true
console.log(verificarEstado('inativo')); // false

// Ate aqui, sem import nem export, este ficheiro e um script: as suas declaracoes de
// topo entrariam no ambito global partilhado com qualquer outro ficheiro do mesmo
// programa que tambem nao tivesse import nem export.
function dobrar(n: number): number {
  return n * 2;
}
const resultado = dobrar(21);
console.log(resultado); // 42

// Se outro ficheiro do mesmo programa declarasse tambem "const resultado" sem
// nenhum import/export, o compilador recusaria por redeclaracao no ambito global.
// A linha seguinte resolve isso: torna este ficheiro um modulo, com ambito proprio,
// sem mudar nada no comportamento observavel deste ficheiro sozinho.
export {};

interface Ponto {
  x: number;
  y: number;
}

type Distancia = number;

interface Etiqueta {
  texto: string;
}

function calcularDistancia(a: Ponto, b: Ponto): Distancia {
  return Math.sqrt((a.x - b.x) ** 2 + (a.y - b.y) ** 2);
}

function criarEtiqueta(texto: string): Etiqueta {
  return { texto };
}

// Os tres tipos ficam so-tipo: nenhum deles produz codigo no JavaScript emitido.
export type { Ponto, Distancia, Etiqueta };

// Os dois valores mantem-se normais: sao os unicos que sobrevivem a compilacao.
export { calcularDistancia, criarEtiqueta };

console.log(calcularDistancia({ x: 0, y: 0 }, { x: 3, y: 4 })); // 5
console.log(criarEtiqueta('novo').texto); // novo

// No JavaScript compilado so restam calcularDistancia e criarEtiqueta: Ponto,
// Distancia e Etiqueta desaparecem por completo, tal como qualquer export type.
